import { motion } from "framer-motion";
import "../App.css";

function AboutPage() {
  // 재사용 가능한 animation variant 정의
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  return (
    <main
      style={{
        padding: "80px 0 0",
        minHeight: "100vh",
        backgroundColor: "#f0f2f5",
        color: "#333",
      }}
    >
      {/* Section 1: Core Values */}
      <motion.section
        className="section-common section-light-bg"
        style={{
          padding: "80px 20px",
          textAlign: "center",
          backgroundColor: "#fcf8f3",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, amount: 0.3 }}
        variants={fadeUp}
      >
        <motion.h2
          className="main-heading"
          style={{ fontSize: "32px", marginBottom: "10px" }}
          variants={fadeUp}
        >
          Assemble와 함께,
        </motion.h2>

        <motion.p
          className="sub-heading"
          style={{ fontSize: "18px", color: "#555", marginBottom: "50px" }}
          variants={fadeUp}
        >
          AI 인테리어 디자인의 새로운 지평을 경험해보세요!
        </motion.p>

        <div
          className="value-grid"
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            gap: "25px",
            maxWidth: "1000px",
            margin: "0 auto",
          }}
        >
          {[
            {
              icon: "fas fa-brain",
              title: "혁신적인 AI 디자인",
              desc: "최첨단 AI 기술로 당신의 취향에 맞는 맞춤형 인테리어 제안.",
            },
            {
              icon: "fas fa-magic",
              title: "손쉬운 공간 변환",
              desc: "몇 번의 클릭만으로 빈 방을 꿈의 공간으로 완벽하게 연출.",
            },
            {
              icon: "fas fa-lightbulb",
              title: "무한한 아이디어 제공",
              desc: "다양한 스타일과 컨셉으로 당신의 영감을 현실로 구현합니다.",
            },
            {
              icon: "fas fa-clock",
              title: "시간과 비용 절약",
              desc: "효율적인 AI 디자인으로 프로젝트 기간과 비용을 획기적으로 절감.",
            },
            {
              icon: "fas fa-sync-alt",
              title: "지속적인 업데이트",
              desc: "최신 디자인 트렌드와 기술을 반영하여 항상 새로운 경험을 제공.",
            },
            {
              icon: "fas fa-globe",
              title: "글로벌 디자인 트렌드",
              desc: "전 세계의 다양한 디자인 트렌드를 반영한 인테리어 솔루션 제공.",
            },
          ].map((item, index) => (
            <motion.div
              key={index}
              className="value-item"
              style={{
                backgroundColor: "#fff",
                padding: "30px",
                borderRadius: "10px",
                boxShadow: "0 5px 15px rgba(0, 0, 0, 0.08)",
                textAlign: "center",
              }}
              variants={fadeUp}
              whileHover={{
                scale: 1.03,
                boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
              }}
              transition={{ duration: 0.3 }}
            >
              <i
                className={`${item.icon} icon`}
                style={{
                  fontSize: "2em",
                  color: "#007bff",
                  marginBottom: "15px",
                }}
              ></i>
              <h3
                style={{
                  fontSize: "1.2em",
                  fontWeight: 600,
                  marginBottom: "10px",
                }}
              >
                {item.title}
              </h3>
              <p
                style={{
                  fontSize: "0.95em",
                  color: "#666",
                  lineHeight: "1.6",
                }}
              >
                {item.desc}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.section>

      {/* Section 2: To Our Users */}
      <motion.section
        className="section-common section-orange-bg"
        style={{
          padding: "80px 20px",
          backgroundColor: "#ffe8cc",
          textAlign: "center",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, amount: 0.3 }}
        variants={fadeUp}
      >
        <motion.h2
          className="main-heading"
          style={{ color: "#333", fontSize: "30px", marginBottom: "10px" }}
          variants={fadeUp}
        >
          TO. 우리의 사용자에게
        </motion.h2>

        <motion.p
          className="sub-heading"
          style={{ fontSize: "18px", color: "#666", marginBottom: "40px" }}
          variants={fadeUp}
        >
          Assemble과 함께 만들어갈 당신만의 공간 스토리를 기대합니다!
        </motion.p>

        <motion.p
          className="story-message"
          style={{
            fontSize: "1.1em",
            fontWeight: 500,
            color: "#007bff",
            marginBottom: "60px",
          }}
          variants={fadeUp}
        >
          <i
            className="fas fa-chevron-circle-right icon"
            style={{ marginRight: "8px" }}
          ></i>
          Assemble의 비전을 확인하세요.
        </motion.p>

        <div
          className="story-cards"
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            gap: "20px",
            maxWidth: "1000px",
            margin: "0 auto",
          }}
        >
          {[
            {
              text: "고객의 만족을 최우선으로, 우리는 끊임없이 기술과 디자인을 연구합니다.",
              title: "우리의 비전",
              color: "#ff6a00",
            },
            {
              text: "AI 기술을 통해 인테리어 디자인의 장벽을 낮추고 모두에게 제공합니다.",
              title: "핵심 가치",
              color: "#ff9130",
            },
            {
              text: "열정적인 팀원들이 만들어가는 Assemble의 미래를 함께하세요.",
              title: "팀 소개",
              color: "#ff9130",
            },
          ].map((card, index) => (
            <motion.div
              key={index}
              className="story-card"
              style={{
                backgroundColor: card.color,
                color: "#fff",
                padding: "30px",
                borderRadius: "10px",
                textAlign: "left",
              }}
              variants={fadeUp}
              whileHover={{ scale: 1.05 }}
              transition={{ duration: 0.3 }}
            >
              <p style={{ fontSize: "1.05em", lineHeight: "1.6", marginBottom: "15px" }}>
                {card.text}
              </p>
              <h3 style={{ fontSize: "1.5em", fontWeight: 700 }}>{card.title}</h3>
            </motion.div>
          ))}
        </div>
      </motion.section>
    </main>
  );
}

export default AboutPage;
